/**
 * GPU Instancing Extension
 *
 * Specification: https://github.com/KhronosGroup/glTF/tree/master/extensions/2.0/Vendor/EXT_mesh_gpu_instancing
 *
 * @private
 */
class GLTFMeshGpuInstancing {

	constructor( writer ) {

		this.writer = writer;
		this.name = 'EXT_mesh_gpu_instancing';

	}

	writeNode( object, nodeDef ) {

		if ( ! object.isInstancedMesh ) return;

		const writer = this.writer;

		const mesh = object;

		const translationAttr = new Float32Array( mesh.count * 3 );
		const rotationAttr = new Float32Array( mesh.count * 4 );
		const scaleAttr = new Float32Array( mesh.count * 3 );

		const matrix = new Matrix4();
		const position = new Vector3();
		const quaternion = new Quaternion();
		const scale = new Vector3();

		for ( let i = 0; i < mesh.count; i ++ ) {

			mesh.getMatrixAt( i, matrix );
			matrix.decompose( position, quaternion, scale );

			position.toArray( translationAttr, i * 3 );
			quaternion.toArray( rotationAttr, i * 4 );
			scale.toArray( scaleAttr, i * 3 );

		}

		const attributes = {
			TRANSLATION: writer.processAccessor( new BufferAttribute( translationAttr, 3 ) ),
			ROTATION: writer.processAccessor( new BufferAttribute( rotationAttr, 4 ) ),
			SCALE: writer.processAccessor( new BufferAttribute( scaleAttr, 3 ) ),
		};

		if ( mesh.instanceColor )
			attributes._COLOR_0 = writer.processAccessor( mesh.instanceColor );

		nodeDef.extensions = nodeDef.extensions || {};
		nodeDef.extensions[ this.name ] = { attributes };

		writer.extensionsUsed[ this.name ] = true;
		writer.extensionsRequired[ this.name ] = true;

	}

}

/**
 * Static utility functions
 *
 * @private
 */
GLTFExporter.Utils = {

	insertKeyframe: function ( track, time ) {

		const tolerance = 0.001; // 1ms
		const valueSize = track.getValueSize();

		const times = new track.TimeBufferType( track.times.length + 1 );
		const values = new track.ValueBufferType( track.values.length + valueSize );
		const interpolant = track.createInterpolant( new track.ValueBufferType( valueSize ) );

		let index;

		if ( track.times.length === 0 ) {

			times[ 0 ] = time;

			for ( let i = 0; i < valueSize; i ++ ) {

				values[ i ] = 0;

			}

			index = 0;

		} else if ( time < track.times[ 0 ] ) {

			if ( Math.abs( track.times[ 0 ] - time ) < tolerance ) return 0;

			times[ 0 ] = time;
			times.set( track.times, 1 );

			values.set( interpolant.evaluate( time ), 0 );
			values.set( track.values, valueSize );

			index = 0;

		} else if ( time > track.times[ track.times.length - 1 ] ) {

			if ( Math.abs( track.times[ track.times.length - 1 ] - time ) < tolerance ) {

				return track.times.length - 1;

			}

			times[ times.length - 1 ] = time;
			times.set( track.times, 0 );

			values.set( track.values, 0 );
			values.set( interpolant.evaluate( time ), track.values.length );

			index = times.length - 1;

		} else {

			for ( let i = 0; i < track.times.length; i ++ ) {

				if ( Math.abs( track.times[ i ] - time ) < tolerance ) return i;

				if ( track.times[ i ] < time && track.times[ i + 1 ] > time ) {

					times.set( track.times.slice( 0, i + 1 ), 0 );
					times[ i + 1 ] = time;
					times.set( track.times.slice( i + 1 ), i + 2 );

					values.set( track.values.slice( 0, ( i + 1 ) * valueSize ), 0 );
					values.set( interpolant.evaluate( time ), ( i + 1 ) * valueSize );
					values.set( track.values.slice( ( i + 1 ) * valueSize ), ( i + 2 ) * valueSize );

					index = i + 1;

					break;

				}

			}

		}

		track.times = times;
		track.values = values;

		return index;

	},

	mergeMorphTargetTracks: function ( clip, root ) {

		const tracks = [];
		const mergedTracks = {};
		const sourceTracks = clip.tracks;

		for ( let i = 0; i < sourceTracks.length; ++ i ) {

			let sourceTrack = sourceTracks[ i ];
			const sourceTrackBinding = PropertyBinding.parseTrackName( sourceTrack.name );
			const sourceTrackNode = PropertyBinding.findNode( root, sourceTrackBinding.nodeName );

			if ( sourceTrackBinding.propertyName !== 'morphTargetInfluences' || sourceTrackBinding.propertyIndex === undefined ) {

				// Tracks that don't affect morph targets, or that affect all morph targets together, can be left as-is.
				tracks.push( sourceTrack );
				continue;

			}

			if ( sourceTrack.createInterpolant !== sourceTrack.InterpolantFactoryMethodDiscrete
				&& sourceTrack.createInterpolant !== sourceTrack.InterpolantFactoryMethodLinear ) {

				if ( sourceTrack.createInterpolant.isInterpolantFactoryMethodGLTFCubicSpline ) {

					// This should never happen, because glTF morph target animations
					// affect all targets already.
					throw new Error( 'THREE.GLTFExporter: Cannot merge tracks with glTF CUBICSPLINE interpolation.' );

				}

				console.warn( 'THREE.GLTFExporter: Morph target interpolation mode not yet supported. Using LINEAR instead.' );

				sourceTrack = sourceTrack.clone();
				sourceTrack.setInterpolation( InterpolateLinear );

			}

			const targetCount = sourceTrackNode.morphTargetInfluences.length;
			const targetIndex = sourceTrackNode.morphTargetDictionary[ sourceTrackBinding.propertyIndex ];

			if ( targetIndex === undefined ) {

				throw new Error( 'THREE.GLTFExporter: Morph target name not found: ' + sourceTrackBinding.propertyIndex );

			}

			let mergedTrack;

			// If this is the first time we've seen this object, create a new
			// track to store merged keyframe data for each morph target.
			if ( mergedTracks[ sourceTrackNode.uuid ] === undefined ) {

				mergedTrack = sourceTrack.clone();

				const values = new mergedTrack.ValueBufferType( targetCount * mergedTrack.times.length );

				for ( let j = 0; j < mergedTrack.times.length; j ++ ) {

					values[ j * targetCount + targetIndex ] = mergedTrack.values[ j ];

				}

				// We need to take into consideration the intended target node
				// of our original un-merged morphTarget animation.
				mergedTrack.name = ( sourceTrackBinding.nodeName || '' ) + '.morphTargetInfluences';
				mergedTrack.values = values;

				mergedTracks[ sourceTrackNode.uuid ] = mergedTrack;
				tracks.push( mergedTrack );

				continue;

			}

			const sourceInterpolant = sourceTrack.createInterpolant( new sourceTrack.ValueBufferType( 1 ) );

			mergedTrack = mergedTracks[ sourceTrackNode.uuid ];

			// For every existing keyframe of the merged track, write a (possibly
			// interpolated) value from the source track.
			for ( let j = 0; j < mergedTrack.times.length; j ++ ) {

				mergedTrack.values[ j * targetCount + targetIndex ] = sourceInterpolant.evaluate( mergedTrack.times[ j ] );

			}

			// For every existing keyframe of the source track, write a (possibly
			// new) keyframe to the merged track. Values from the previous loop may
			// be written again, but keyframes are de-duplicated.
			for ( let j = 0; j < sourceTrack.times.length; j ++ ) {

				const keyframeIndex = this.insertKeyframe( mergedTrack, sourceTrack.times[ j ] );
				mergedTrack.values[ keyframeIndex * targetCount + targetIndex ] = sourceTrack.values[ j ];

			}

		}

		clip.tracks = tracks;

		return clip;

	},

	toFloat32BufferAttribute: function ( srcAttribute ) {

		const dstAttribute = new BufferAttribute( new Float32Array( srcAttribute.count * srcAttribute.itemSize ), srcAttribute.itemSize, false );

		if ( ! srcAttribute.normalized && ! srcAttribute.isInterleavedBufferAttribute ) {

			dstAttribute.array.set( srcAttribute.array );

			return dstAttribute;

		}

		for ( let i = 0, il = srcAttribute.count; i < il; i ++ ) {

			for ( let j = 0; j < srcAttribute.itemSize; j ++ ) {

				dstAttribute.setComponent( i, j, srcAttribute.getComponent( i, j ) );

			}

		}

		return dstAttribute;

	}

};

/**
 * @param {THREE.Object3D} root
 */
function disposeObject3D(root) {
  const geometries = new Set();
  const materials = new Set();

  root.traverse((child) => {
    if (!child.isMesh) return;
    if (child.geometry && !geometries.has(child.geometry)) {
      geometries.add(child.geometry);
      child.geometry.dispose();
    }
    const mats = Array.isArray(child.material) ? child.material : [child.material];
    for (const m of mats) {
      if (m && !materials.has(m)) {
        materials.add(m);
        m.dispose();
      }
    }
  });
}

/**
 * Генерирует полностью автономный HTML-файл открытки:
 * весь 3D-букет встраивается как base64-GLB, текст — обычный HTML (неподвижный),
 * вращение через OrbitControls затрагивает только букет.
 *
 * @param {string} glbBase64
 * @param {string[]} paragraphs
 * @returns {string}
 */
function buildStandaloneCard(glbBase64, paragraphs, standaloneRuntime) {
  const esc = (s) =>
    s
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");

  const textHtml = paragraphs.map((p) => "<p>" + esc(p) + "</p>").join("\n");

  return `<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>3D открытка</title>
<style>
*,
*::before,
*::after { box-sizing: border-box; }

html,
body { margin: 0; min-height: 100%; }

body {
  font-family: "Source Sans 3", system-ui, sans-serif;
  background: radial-gradient(ellipse at 30% 0%, #3d2a35 0%, #1a1520 45%, #0f1115 100%);
  color: #2c2419;
}

.postcard-wrap {
  max-width: 960px;
  margin: 2rem auto 2.5rem;
  padding: 0 1rem;
}

.postcard {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  background: linear-gradient(165deg, #fffef9 0%, #faf3eb 42%, #f5ebe3 100%);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(255, 255, 255, 0.08);
  padding: 2rem 1.75rem 2.25rem;
}

.postcard__ornament {
  position: absolute;
  top: 1.25rem;
  right: 1.5rem;
  width: 64px;
  height: 64px;
  border: 1px solid rgba(180, 120, 140, 0.35);
  border-radius: 50%;
  opacity: 0.45;
  pointer-events: none;
  z-index: 2;
}

.postcard__ornament::after {
  content: "";
  position: absolute;
  inset: 11px;
  border: 1px solid rgba(180, 120, 140, 0.25);
  border-radius: 50%;
}

.postcard__flow::after { content: ""; display: block; clear: both; }

.postcard__bouquet {
  --bouquet-w: min(500px, 44vw);
  float: left;
  width: var(--bouquet-w);
  height: 700px;
  margin: 0 1.35rem 1rem 0;
  shape-outside: inset(0 round 14px);
  shape-margin: 0.75rem;
  border-radius: 14px;
  overflow: hidden;
  background: linear-gradient(160deg, #f8f0f4 0%, #e8dce8 35%, #d4c4d0 100%);
  box-shadow: 0 8px 28px rgba(80, 50, 70, 0.2), inset 0 0 0 1px rgba(255, 255, 255, 0.65);
  display: flex;
  flex-direction: column;
  position: relative;
}

.postcard__bouquet-label {
  margin: 0;
  padding: 0.45rem 0.6rem;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-align: center;
  color: #7a4a5c;
  background: rgba(255, 255, 255, 0.55);
  border-bottom: 1px solid rgba(180, 120, 140, 0.2);
  flex-shrink: 0;
}

.postcard__viewport {
  flex: 1;
  width: 100%;
  min-height: 300px;
  touch-action: none;
  position: relative;
  z-index: 1;
}

.postcard__viewport canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.postcard__hint {
  margin: 0;
  padding: 0.35rem 0.5rem;
  font-size: 0.68rem;
  color: #6b5560;
  text-align: center;
  background: rgba(255, 255, 255, 0.5);
  flex-shrink: 0;
}

.postcard__copy { text-align: justify; hyphens: auto; }

.postcard__copy p {
  margin: 0 0 1.1em;
  font-family: "Cormorant Garamond", "Times New Roman", serif;
  font-size: clamp(1.05rem, 1.1vw + 0.75rem, 1.3rem);
  line-height: 1.55;
  color: #2c2419;
}

.postcard__copy p:first-child::first-letter {
  font-size: 2.4em;
  float: left;
  line-height: 0.85;
  padding-right: 0.12em;
  padding-top: 0.06em;
  font-weight: 600;
  color: #8b4a62;
}

@media (max-width: 720px) {
  .postcard__bouquet {
    float: none;
    width: 100%;
    max-width: 360px;
    height: 340px;
    margin: 0 0 1.25rem;
    shape-outside: none;
  }
}

@media print {
  @page {
    size: A4 landscape;
    margin: 8mm;
  }

  html,
  body {
    background: #fff;
  }

  .postcard__hint,
  .postcard__ornament {
    display: none !important;
  }

  .postcard-wrap {
    margin: 0;
    padding: 0;
    max-width: none;
  }

  .postcard {
    box-shadow: none;
    border: 1px solid #ddd;
    break-inside: avoid;
    page-break-inside: avoid;
    padding: 10mm 8mm;
  }

  .postcard__bouquet {
    float: left;
    width: 46%;
    max-width: none;
    height: 132mm;
    margin: 0 8mm 4mm 0;
    shape-outside: none;
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .postcard__viewport {
    min-height: 0;
  }

  .postcard__copy p {
    orphans: 3;
    widows: 3;
  }
}
</style>
</head>
<body>
<main class="postcard-wrap">
  <article class="postcard" aria-label="Открытка с букетом и текстом">
    <div class="postcard__ornament" aria-hidden="true"></div>
    <div class="postcard__flow">
      <figure class="postcard__bouquet" aria-label="3D букет">
        <figcaption class="postcard__bouquet-label">Букет</figcaption>
        <div id="scene" class="postcard__viewport"></div>
        <p class="postcard__hint">Вращайте букет мышью или пальцем</p>
      </figure>
      <div class="postcard__copy">${textHtml}</div>
    </div>
  </article>
</main>
<script>${standaloneRuntime}</script>
<script>
var { THREE, OrbitControls, GLTFLoader } = window.StandaloneCardDependencies;
var viewport = document.getElementById("scene");
var renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
viewport.appendChild(renderer.domElement);

var scene = new THREE.Scene();
var camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100);
camera.position.set(0, 0, 6);

var controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.8;
controls.minDistance = 0.5;
controls.maxDistance = 25;
controls.target.set(0, 0, 0);

scene.add(new THREE.AmbientLight(0xffffff, 0.6));
scene.add(new THREE.HemisphereLight(0xfff5f8, 0x6a5a62, 1.15));
var key = new THREE.DirectionalLight(0xffffff, 1.4);
key.position.set(4, 9, 6);
scene.add(key);
var fill = new THREE.DirectionalLight(0xffe8f0, 0.65);
fill.position.set(-5, 4, 3);
scene.add(fill);

var loader = new GLTFLoader();
var raw = atob("${glbBase64}");
var bytes = new Uint8Array(raw.length);
for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);

function resize() {
  var w = Math.max(viewport.clientWidth, 1);
  var h = Math.max(viewport.clientHeight, 1);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  // updateStyle = false — не фиксируем канва в пикселях экрана,
  // иначе при печати (вёрстка пересчитывается под ширину бумаги)
  // холст вылезет из рамки и обрежется по overflow:hidden.
  renderer.setSize(w, h, false);
}

function renderForPrint() {
  resize();
  controls.update();
  renderer.render(scene, camera);
}
window.addEventListener("beforeprint", renderForPrint);
window.addEventListener("afterprint", renderForPrint);

loader.parse(
  bytes.buffer,
  "",
  function (gltf) {
    var model = gltf.scene;
    scene.add(model);
    model.updateMatrixWorld(true);
    var box = new THREE.Box3().setFromObject(model);
    var size = box.getSize(new THREE.Vector3());
    var center = box.getCenter(new THREE.Vector3());
    var maxDim = Math.max(size.x, size.y, size.z, 1e-8);
    var distance = (maxDim / 2 / Math.tan((camera.fov * Math.PI) / 360)) * 1.22;
    model.position.sub(center);
    model.updateMatrixWorld(true);
    camera.position.set(0, size.y * 0.08, distance);
    camera.near = Math.max(distance / 500, 0.01);
    camera.far = Math.max(distance * 50, 50);
    camera.updateProjectionMatrix();
    camera.lookAt(0, 0, 0);
    controls.target.set(0, 0, 0);
    controls.update();
    resize();
  },
  function (err) {
    console.error(err);
  }
);

resize();
new ResizeObserver(resize).observe(viewport);

function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>`;
}

