const FOOTPRINT_RADIUS_FACTOR = 0.31;
const MODELS_DIR = "glb/";
const JSON_DIR = "models/";
const BOUQUET_INDEX_URL = `${JSON_DIR}bouquets.json`;
const TEXT_URL = "text.txt";
const TEXT_URL2 = "textMain.txt";
//const MANIFEST_URL = `${MODELS_DIR}manifest.json`;
const BOUQUET_TITLE = "Букет";

const textEl = document.getElementById("card-text");
const viewportEl = document.getElementById("card-scene");
const statusEl = document.getElementById("card-scene-status");
const nextBouquetBtn = document.getElementById("next-bouquet");
const bouquetFiles = [];
let currentBouquetIndex = 0;
let isBouquetLoading = false;
let sceneStarted = false;
let sceneResizeObserver = null;
let sceneAnimationId = 0;
const savePdfBtn = document.getElementById("card-save-pdf");
const saveHtmlBtn = document.getElementById("card-save-html");
const saveBqtBtn = document.getElementById("save-bouquet");
let radiusMultiplier;
let heightMultiplier;
let history;
let animations1, mixer1;   
let tilt, opts;
/** @type {{ scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer, controls: OrbitControls, bouquet: THREE.Group | null } | null} */
let viewRef = null;
//const bouquetFlowers = JSON.parse(localStorage.getItem('bouquetFlowers'));

/** @type {string[]} */
let cardParagraphs = [];

/**
 * @param {string} raw
 * @returns {string[]}
 */
let testRead = [];
  setSceneStatus(`Загрузка «${BOUQUET_TITLE}»…`);
  await waitForLayout(viewportEl);

  const scene = new Scene();
  scene.background = new Color(0xe8dde6);
  const camera = new PerspectiveCamera(45, 1, 0.01, 1000);
  const renderer = new WebGLRenderer({
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true,
  });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = SRGBColorSpace;
  viewportEl.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.06;
  controls.minDistance = 0.15;
  controls.maxDistance = 20;
  controls.autoRotate = true;
  controls.autoRotateSpeed = 0.75;
  controls.target.set(0, 0.5, 0);

  viewRef = { scene, camera, renderer, controls, bouquet: null };

  scene.add(new AmbientLight(0xffffff, 0.55));
  scene.add(new HemisphereLight(0xfff5f8, 0x6a5a62, 1.2));
  const key = new DirectionalLight(0xffffff, 1.35);
  key.position.set(4, 9, 6);
  scene.add(key);
  const fill = new DirectionalLight(0xffe8f0, 0.65);
  fill.position.set(-5, 4, 3);
  scene.add(fill);

  const loader = new GLTFLoader();
  let bouquet = null;

  function resizeRenderer() {
    const w = Math.max(viewportEl.clientWidth, 1);
    const h = Math.max(viewportEl.clientHeight, 1);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    // updateStyle = false: не пишем inline width/height в canvas.
    // Размер рисуется только буфером (canvas.width/height), а экранный
    // размер задаёт CSS (.postcard__viewport canvas { width:100% }).
    // Иначе канва зафиксирован в пикселях экрана, а при печати вёрстка
    // пересчитывается под ширину бумаги — холст вылезает из рамки
    // и обрезается по overflow:hidden, в PDF попадает только левая часть.
    renderer.setSize(w, h, false);
    keepBouquetInFrame();
  }

function normalizeManifest(data) {
	console.log('data  ',data);
  if (Array.isArray(data)) return data;
  if (data && typeof data === "object") {
    const o = /** @type {Record<string, unknown>} */ (data);
    if (o.file || o.bouquet || o.title) return [o];
  }
  return [];
}

async function initBouquetScene(manifestFile = "manifest.json") {
	if (!viewportEl) return false;
    setSceneStatus(`Загрузка «${manifestFile}»…`);
    const manifestUrl = `${JSON_DIR}${encodeURIComponent(manifestFile)}`;
    const res = await fetch(manifestUrl);
    if (!res.ok) throw new Error(`${manifestFile} недоступен`);
    const entries = normalizeManifest(await res.json());
    console.log(entries);	
	history = entries;
	testRead = [];
/* 	history = JSON.parse(sessionStorage.getItem('cardHistory') || '[]');
	console.log('typeof str', typeof history); */
	const combinedBouquet = new Group();
	combinedBouquet.name = "GlbBouquetCombined";
	let anyLoaded = false;
	for (const entry of entries) {
		console.log('typeof', typeof entry);
		console.log('entry', entry);
		testRead = Array.isArray(entry.testRead) ? entry.testRead.slice() : [];
		console.log('testRead  ', testRead);
		let ll = testRead.length;
		console.log('ll  ', ll);
		radiusMultiplier = testRead[ll - 2][2];
		heightMultiplier = testRead[ll - 2][3];
		console.log('radiusMultiplier ',radiusMultiplier);
		testRead[ll - 1][2];
		testRead.splice(-2);
		console.log('testRead  ', testRead);
		
	  try {
		const opts = await resolveBouquetOptions();
		console.log('opts 548 ',opts);
		bouquet = await loadGlbBouquet(loader, opts);
		prepareMaterials(bouquet);
		combinedBouquet.add(bouquet);
		// scaleObjectToMaxDimension(bouquet, 2.85);								   
		bouquet.position.x -= 0.22;
		bouquet.position.y += 0.14;
		bouquet.updateMatrixWorld(true);

		const meshCount = countMeshes(bouquet);
		if (meshCount === 0) {
		  throw new Error("Модели загружены, но в сцене нет мешей");
		}
		anyLoaded = true;
	  } catch (err) {
		const message =
		  err instanceof Error ? err.message : "Ошибка загрузки букета";
		setSceneStatus(message, "error");
		console.error("Букет:", err);
	  }
	}

	if (anyLoaded) {
		scaleObjectToMaxDimension(combinedBouquet, 2.85);
		const previousBouquet = viewRef.bouquet;
		if (previousBouquet) {
			scene.remove(previousBouquet);
			disposeObject3D(previousBouquet);
		}
		scene.add(combinedBouquet);
		bouquet = combinedBouquet;
		viewRef.bouquet = combinedBouquet;
		resizeRenderer();
		const center = fitCameraToObject(camera, combinedBouquet, 1.22);
		if (!center) {
		  setSceneStatus("Не удалось рассчитать рамки букета", "error");
		} else {
		  controls.target.copy(center);
		}
		controls.update();

		setSceneStatus("", "hidden");
		if (saveHtmlBtn) saveHtmlBtn.disabled = false;
		if (saveBqtBtn) saveBqtBtn.disabled = false;
		viewRef.bouquet = combinedBouquet;
	} else {
		if (saveHtmlBtn) saveHtmlBtn.disabled = true;
		if (saveBqtBtn) saveBqtBtn.disabled = true;
	}

	if (!sceneStarted) {
		sceneResizeObserver = new ResizeObserver(resizeRenderer);
		sceneResizeObserver.observe(viewportEl);
		function animate() {
			sceneAnimationId = requestAnimationFrame(animate);
			controls.update();
			renderer.render(scene, camera);
		}
		animate();

		function renderForPrint() {
			resizeRenderer();
			controls.update();
			renderer.render(scene, camera);
		}
		window.addEventListener("beforeprint", renderForPrint);
		window.addEventListener("afterprint", renderForPrint);

		window.addEventListener(
			"pagehide",
			() => {
			  cancelAnimationFrame(sceneAnimationId);
			  sceneResizeObserver?.disconnect();
			  controls.dispose();
			  renderer.dispose();
			  viewRef = null;
			  if (bouquet) disposeObject3D(bouquet);
			},
			{ once: true }
		);
		sceneStarted = true;
	}
	return anyLoaded;
}

async function loadBouquetCatalog() {
  const res = await fetch(BOUQUET_INDEX_URL);
  if (!res.ok) throw new Error("Список букетов недоступен");
  const files = await res.json();
  if (!Array.isArray(files)) throw new Error("Некорректный список букетов");
  bouquetFiles.push(
    ...files.filter((file) => typeof file === "string" && file.endsWith(".json"))
  );
  if (bouquetFiles.length === 0) throw new Error("В списке нет букетов");
  const defaultIndex = bouquetFiles.indexOf("manifest.json");
  currentBouquetIndex = defaultIndex >= 0 ? defaultIndex : 0;
}

async function showNextBouquet() {
  if (isBouquetLoading || bouquetFiles.length < 2) return;
  isBouquetLoading = true;
  if (nextBouquetBtn) nextBouquetBtn.disabled = true;
  const nextIndex = (currentBouquetIndex + 1) % bouquetFiles.length;

  try {
    if (await initBouquetScene(bouquetFiles[nextIndex])) {
      currentBouquetIndex = nextIndex;
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : "Ошибка загрузки букета";
    setSceneStatus(message, "error");
    console.error("Букет:", err);
  } finally {
    isBouquetLoading = false;
    if (nextBouquetBtn) nextBouquetBtn.disabled = bouquetFiles.length < 2;
  }
}

async function startBouquetScene() {
  try {
    await loadBouquetCatalog();
    const loaded = await initBouquetScene(bouquetFiles[currentBouquetIndex]);
    if (nextBouquetBtn) {
      nextBouquetBtn.disabled = !loaded || bouquetFiles.length < 2;
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : "Ошибка загрузки букета";
    setSceneStatus(message, "error");
    console.error("Букет:", err);
  }
}

function bindSaveButtons() {
  if (savePdfBtn) {
    savePdfBtn.addEventListener("click", () => savePostcardAsPdf());
  }
  if (saveHtmlBtn) {
    saveHtmlBtn.disabled = true;
    saveHtmlBtn.addEventListener("click", () => savePostcardAsHtml());
  }
  if (saveBqtBtn) {
    saveBqtBtn.disabled = true;
    saveBqtBtn.addEventListener("click", () => saveBouquet());
  }
  if (nextBouquetBtn) {
    nextBouquetBtn.disabled = true;
    nextBouquetBtn.addEventListener("click", () => showNextBouquet());
  }
}

loadCardText();
bindSaveButtons();
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => startBouquetScene());
} else {
  startBouquetScene();
}
