/**
 * Выравнивает модель: центр по XZ, основание на Y = 0.
 * @param {THREE.Object3D} object
 */
function alignModelBase(object) {
  object.updateMatrixWorld(true);
  const box = new Box3().setFromObject(object);
  object.position.x -= (box.min.x + box.max.x) / 2;
  object.position.y -= box.min.y;
  object.position.z -= (box.min.z + box.max.z) / 2;
}
/**
 * @param {THREE.Object3D} object
 * @returns {THREE.Vector3}
 */
function getModelSize(object) {
  object.updateMatrixWorld(true);
  return new Box3().setFromObject(object).getSize(new Vector3());
}

/**
 * @param {THREE.Object3D} object
 * @returns {number}
 */
function getModelFootprint(object) {
  const size = getModelSize(object);
  return Math.max(size.x, size.y, size.z, 0.001);
}

/**
 * Эталонный «след» букета — по самому компактному цветку (радиус не раздувается).
 * @param {number[]} footprints
 * @returns {number}
 */
function computeReferenceFootprint(footprints) {
  return Math.min(...footprints, 0.001);
}

/**
 * Масштаб стебля: крупные модели уменьшаются до эталона, мелкие не увеличиваются.
 * @param {number} footprint
 * @param {number} referenceFootprint
 * @returns {number}
 */
function computeStemFitScale(footprint, referenceFootprint) {
  if (footprint <= referenceFootprint) return 1;
  return referenceFootprint / footprint;
}

/**
 * @param {number} referenceFootprint
 * @param {number} radiusScale
 * @param {number | undefined} explicitRadius
 * @returns {number}
 */
function computeBouquetRadius(referenceFootprint, radiusScale = 1, explicitRadius) {
  const auto = referenceFootprint * FOOTPRINT_RADIUS_FACTOR * radiusScale * radiusMultiplier;
  if (typeof explicitRadius === "number" && explicitRadius > 0) {
    return Math.max(auto, explicitRadius);
  }
  return auto;
}

function parseTextParagraphs(raw) {
  const paragraphs = [];
  let block = [];

  for (const line of raw.replace(/\r\n/g, "\n").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) {
      if (block.length) {
        paragraphs.push(block.join(" "));
        block = [];
      }
      continue;
    }
    block.push(trimmed);
  }
  if (block.length) paragraphs.push(block.join(" "));
  return paragraphs;
}

function renderText(paragraphs) {
  cardParagraphs = paragraphs;
  textEl.innerHTML = "";
  for (const text of paragraphs) {
    const p = document.createElement("p");
    p.textContent = text;
    textEl.appendChild(p);
  }
}

function showTextError(message) {
  textEl.innerHTML = "";
  const p = document.createElement("p");
  p.className = "postcard__error";
  p.textContent = message;
  textEl.appendChild(p);
}

function setSceneStatus(message, type = "loading") {
  if (!statusEl) return;
  statusEl.textContent = message;
  statusEl.classList.remove("postcard__scene-status--hidden", "postcard__scene-status--error");
  if (type === "hidden") {
    statusEl.classList.add("postcard__scene-status--hidden");
  } else if (type === "error") {
    statusEl.classList.add("postcard__scene-status--error");
  }
}

async function loadCardText() {
  let res = await fetch(TEXT_URL);
  if (!res.ok) {
	res = await fetch(TEXT_URL2);
  }
  const raw = await res.text();
  const paragraphs = parseTextParagraphs(raw);
  if (paragraphs.length === 0) {
    showTextError("Файл text.txt пуст.");
    return;
  }
  renderText(paragraphs);
}

async function loadGlbBouquet(loader, options) {
  const stems = options.stems ?? [];
  if (stems.length === 0) {
    throw new Error("Букет: не заданы стебли (stems)");
  }

  tilt = options.tilt ?? 0.14;
  const radiusScale = options.radiusScale ?? 1;

  const uniqueUrls = [...new Set(stems.map((s) => s.url))];
  /** @type {Map<string, { template: THREE.Object3D, footprint: number }>} */
  const templates = new Map();

  await Promise.all(
    uniqueUrls.map(async (url) => {
      const template = await loadTemplate(loader, url);
      templates.set(url, {
        template,
        footprint: getModelFootprint(template),
      });
    })
  );

  /** @type {{ url: string, scale?: number }[]} */
  	  console.log('stems 217 ',stems);
  const stemPlacements = [];
  for (const spec of stems) {
    const n = Math.max(1, Math.floor(spec.count ?? 1));
    for (let i = 0; i < n; i++) {
      stemPlacements.push({ url: spec.url, scale: spec.scale });
    }
  }
  console.log('stemPlacements 225 ',stemPlacements);

  const footprints = [...templates.values()].map((t) => t.footprint);
  const referenceFootprint = computeReferenceFootprint(footprints);
  const radius = computeBouquetRadius(referenceFootprint, radiusScale, options.radius);
  const count = stemPlacements.length;

  const bouquet = new Group();
  bouquet.name = "GlbBouquet";

  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const { url, scale: stemScaleOverride } = stemPlacements[i];
    const { template, footprint } = templates.get(url);

    const slot = new Group();
    slot.rotation.y = angle;

    const instance = template.clone(true);
    const fitScale = computeStemFitScale(footprint, referenceFootprint);
    const manualScale = typeof stemScaleOverride === "number" && stemScaleOverride > 0 ? stemScaleOverride : 1;
    let s = fitScale * manualScale;
	console.log('s 250 ',s);
    instance.scale.set(s, s, s);

    instance.position.set(0, 0, radius);
    instance.rotation.y = Math.PI;
    instance.rotation.x = tilt;
    instance.rotation.order = "YXZ";

    slot.add(instance);
    bouquet.add(slot);
  }

  return bouquet;
}

/**
 * @param {import("three/addons/loaders/GLTFLoader.js").GLTFLoader} loader
 * @param {string} url
 * @returns {Promise<THREE.Object3D>}
 */
function loadTemplate(loader, url) {
  return new Promise((resolve, reject) => {
    loader.load(
      url,
      (gltf) => {
		animations1 = gltf.animations;   
		if (animations1 && animations1.length) {
			// Создаем анимационный микшер
			mixer1 = new AnimationMixer(gltf.scene);  
			// Проигрываем все анимации
			animations1.forEach((clip) => {
				mixer1.clipAction(clip).play();
			});
		}   
        const template = gltf.scene;
        alignModelBase(template);
        resolve(template);
      },
      undefined,
      reject
    );
  });
}

function parseBouquetManifest(bouquet) {
  const b = bouquet;
  console.log('b 284 ',b);
  opts = {
    count: typeof b.count === "number" ? b.count : undefined,
    radius: typeof b.radius === "number" ? b.radius : undefined,
    radiusScale: typeof b.radiusScale === "number" ? b.radiusScale : undefined,
    tilt: typeof b.tilt === "number" ? b.tilt : tilt,
    stems: /** @type {BouquetStemSpec[]} */ ([]),
  };
    for (let raw of b) {     
      let item = /** @type {Record<string, unknown>} */ raw;
	  /* if(item[0] == 'r0') { radiusMultiplier = item[2];heightMultiplier = item[3]; continue; } */
	  console.log('item  ',item);
      opts.stems.push({
        url: item[1],
        count: item[2],
        scale: item[3] 
      });
    }
	console.log('opts 244 ',opts);
 if (opts.stems.length === 0) return null;
  return opts;
}
