/**
 * @param {Blob} blob
 * @param {string} filename
 */
function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

async function savePostcardAsHtml() {
  if (!viewRef?.bouquet) {
    alert("Подождите, пока загрузится букет.");
    return;
  }
  if (cardParagraphs.length === 0) {
    alert("Текст открытки ещё не загружен.");
    return;
  }

  if (saveHtmlBtn) saveHtmlBtn.disabled = true;

  try {
    const exporter = new GLTFExporter();
    const result = await new Promise((resolve, reject) => {
      exporter.parse(viewRef.bouquet, resolve, reject, { binary: true });
    });
    if (!(result instanceof ArrayBuffer)) {
      throw new Error("Экспорт букета не вернул бинарный GLB");
    }

    const bytes = new Uint8Array(result);
    const chunks = [];
    const CHUNK = 0x8000;
    for (let i = 0; i < bytes.length; i += CHUNK) {
      chunks.push(String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK)));
    }
    const base64 = btoa(chunks.join(""));

    const html = buildStandaloneCard(base64, cardParagraphs, standaloneRuntime);
    downloadBlob(
      new Blob([html], { type: "text/html;charset=utf-8" }),
      "3d-otkrytka.html"
    );
  } catch (err) {
    console.error(err);
    alert(
      err instanceof Error
        ? `Не удалось сохранить открытку: ${err.message}`
        : "Не удалось сохранить открытку."
    );
  } finally {
    if (saveHtmlBtn) saveHtmlBtn.disabled = false;
  }
}
